-- English localization and Lachlan diplomacy.

INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_CIV_ROMAN_GLADIUS_DESC','The RomanGladius Network'),
('TXT_KEY_CIV_ROMAN_GLADIUS_SHORT_DESC','RomanGladius Network'),
('TXT_KEY_CIV_ROMAN_GLADIUS_ADJECTIVE','RomanGladius'),
('TXT_KEY_CIV_ROMAN_GLADIUS_PEDIA','The RomanGladius Network is a federation of multiplayer Servers founded and maintained by Lachlan "RomanGladius." Its strength comes from a lively player community, careful staff management, trusted administrators, and the reputation earned by keeping every Server welcoming, stable, and online.'),
('TXT_KEY_CIV5_ROMAN_GLADIUS_HEADING_1','A Stronger Server Builds a Brighter World'),
('TXT_KEY_CIV5_ROMAN_GLADIUS_TEXT_1','Every City is a Server and every Citizen is a Player. Growth brings activity and revenue, but large communities demand moderators, administrators, and quick decisions when incidents appear in chat.'),
('TXT_KEY_CIV_ROMAN_GLADIUS_STRATEGY','Grow a small number of very large Servers. Every 2 Players provide +1 Gold, every 4 provide +1 Science, and every 5 provide +1 Culture. Use the Network Dashboard to appoint roughly one Moderator per 4–6 Players and one Administrator in large Servers. Maintain high Reputation for Food, Gold, and Culture bonuses, resolve Server Events, and claim permanent Network Milestones. New Servers are expensive: Server Owners cost 60% more Production, remove 2 Population when trained, and founding costs 100 Gold for every Server you already control.'),

('TXT_KEY_LEADER_ROMAN_GLADIUS','Lachlan "RomanGladius"'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_PEDIA','Lachlan built his Network less as a distant ruler than as its permanent Owner: visible in chat, patient with new Players, and willing to step into disputes before they consumed the community. His greatest achievement was not a single world, but a culture in which people returned to build together.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_ROMAN_GLADIUS_HEADING_1','The Owner Online'),
('TXT_KEY_CIVILOPEDIA_LEADERS_ROMAN_GLADIUS_TEXT_1','To Lachlan, administration is a form of stewardship. A successful Server needs clear rules, trusted staff, technical maintenance, and enough room for ordinary Players to make the world their own.'),

('TXT_KEY_TRAIT_ROMAN_GLADIUS_SHORT','The Server Network'),
('TXT_KEY_TRAIT_ROMAN_GLADIUS_HELP','Every City is a Server and every point of Population is a Player. Every 2 Players provide +1 [ICON_GOLD] Gold, every 4 provide +1 [ICON_RESEARCH] Science, and every 5 provide +1 [ICON_CULTURE] Culture. Manage persistent 0–100 Reputation, Moderators, Administrators, Chat, and Server Events through the Network Dashboard. High Reputation improves Food, Gold, and Culture; poor management can drive Players away. The Capital has Owner Online: +10% [ICON_PRODUCTION] Production, +10% [ICON_GOLD] Gold, and +10 Reputation equilibrium.'),

('TXT_KEY_UNIT_ROMAN_GLADIUS_SERVER_OWNER','Server Owner'),
('TXT_KEY_UNIT_ROMAN_GLADIUS_SERVER_OWNER_PEDIA','A Server Owner carries the tools, permissions, and responsibility needed to launch another community. The work is expensive because every new Server must be hosted, configured, staffed, and connected to the wider Network.'),
('TXT_KEY_UNIT_ROMAN_GLADIUS_SERVER_OWNER_STRATEGY','A costly Settler replacement. Training consumes 2 Population. Founding the second Server costs 100 Gold, the third 200 Gold, and so on. A new Server begins with a free Server Console, 60 Reputation, and +50% Food for 10 turns.'),
('TXT_KEY_UNIT_ROMAN_GLADIUS_SERVER_OWNER_HELP','Replaces the Settler. Costs 60% more [ICON_PRODUCTION] Production and consumes 2 [ICON_CITIZEN] Population when trained. Launching a Server costs 100 [ICON_GOLD] Gold per existing Server; the new Server receives a free Server Console, 60 Reputation, and Grand Opening for 10 turns.'),

('TXT_KEY_BUILDING_ROMAN_GLADIUS_SERVER_CONSOLE','Server Console'),
('TXT_KEY_BUILDING_ROMAN_GLADIUS_SERVER_CONSOLE_PEDIA','Part operations room, part town hall, the Server Console is where staff watch performance, review chat, investigate incidents, restore backups, and keep the community connected.'),
('TXT_KEY_BUILDING_ROMAN_GLADIUS_SERVER_CONSOLE_STRATEGY','A Monument replacement providing +2 Culture and +1 Gold. It unlocks that City''s roster, staff actions, reputation, chat, logs, and event choices in the Network Dashboard. Server Owners construct one for free when founding a City.'),
('TXT_KEY_BUILDING_ROMAN_GLADIUS_SERVER_CONSOLE_HELP','Replaces the Monument. +2 [ICON_CULTURE] Culture and +1 [ICON_GOLD] Gold. Unlocks Server Management, Reputation, Chat, staff promotion, event choices, and logs for this Server.'),
('TXT_KEY_BUILDING_ROMAN_GLADIUS_DUMMY','RomanGladius Network Runtime Effect'),

('TXT_KEY_ROMAN_GLADIUS_DAWN_OF_MAN','Owner, the Main Server is online. Its first Players are already building, trading stories, and calling for you in chat. If this community is to endure, enthusiasm alone will not be enough.[NEWLINE][NEWLINE]Appoint trusted Moderators. Promote a capable Administrator. Protect the Network''s Reputation through crashes, griefers, exploits, and staff disputes, then let every successful Server share in the strength of the whole.[NEWLINE][NEWLINE]Lachlan, will you build a community where everyone can play, build, and belong?'),

('TXT_KEY_CITY_ROMAN_GLADIUS_1','Main Server'),('TXT_KEY_CITY_ROMAN_GLADIUS_2','Survival Server'),
('TXT_KEY_CITY_ROMAN_GLADIUS_3','Creative Server'),('TXT_KEY_CITY_ROMAN_GLADIUS_4','PvP Server'),
