INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_LEADER_ROMAN_GLADIUS_FIRSTGREETING_1','Welcome to the Network. There is room for another good neighbour—just keep the chat civil and the connection steady.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_GREETING_NEUTRAL_1','Owner online. What can the Network do for you?'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_GREETING_HOSTILE_1','The logs remember what happened, even if you would rather they did not.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_DOW_1','You have made this Network less safe for everyone. The staff are ready, and the ban is permanent.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_ATTACKED_1','So that is your idea of community. Very well—we know how to handle griefers.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_DEFEATED_1','The Server is going dark. Look after the people who remain.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_PEACE_1','Let us restore the world and give the Players something better to build.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_TRADE_ACCEPT_1','That keeps both Networks running.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_TRADE_REJECT_1','That configuration will not work for us.'),
('TXT_KEY_LEADER_ROMAN_GLADIUS_DENOUNCED_1','You could have opened a support ticket.' );
